def policy(obs, P):
    x = obs[0]
    y = obs[1]
    vx = obs[2]
    vy = obs[3]
    angle = obs[4]
    ang_v = obs[5]
    leg_left = obs[6]
    leg_right = obs[7]
    if y <= P["y_t"] and vy <= P["vy_t"] and x <= P["x_main"]:
        return 2
    if vy <= P["vy_fast"] and y <= P["y_t"] and x <= P["x_main"]:
        return 2
    if abs(angle) > P["ang_t"]:
        return 1
    if ang_v > P["angv_t"]:
        return 3
    if ang_v < -P["angv_t"]:
        return 1
    if leg_left > P["leg_t"] or leg_right > P["leg_t"]:
        if x <= P["x_ground"]:
            if vx > P["vx_t"]:
                return 1
            return 3
        else:
            if vx > P["vx_t"]:
                return 1
            return 0
    if vy <= P["vy_t"] and y > P["y_t"]:
        return 0
    if x <= -P["x_t"]:
        if vx <= P["vx_small"]:
            return 3
        return 1
    if x > P["x_main"]:
        if y <= P["y_t"] and vy <= P["vy_t"]:
            return 0
        return 1
    if x > P["x_t"]:
        return 1
    if vx > P["vx_t"]:
        return 1
    if vx < -P["vx_t"]:
        return 3
    return 0
